CREATE TYPE public.decoder_status AS ENUM ('ready', 'done');
CREATE DOMAIN public.decoder_code AS integer CHECK (VALUE >= 0);
CREATE TABLE public.decoder_indexed (payload text, id integer PRIMARY KEY, status public.decoder_status, optional text);
CREATE TABLE public.decoder_full (label text, optional text);
ALTER TABLE public.decoder_full REPLICA IDENTITY FULL;
CREATE TABLE public.decoder_domain (id integer PRIMARY KEY, code public.decoder_code);
CREATE TABLE public.decoder_generated (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, value integer, doubled integer GENERATED ALWAYS AS (value * 2) STORED);
CREATE TABLE public.decoder_spilled (id integer PRIMARY KEY, payload text);
CREATE PUBLICATION decoder_fixture_publication FOR TABLE public.decoder_indexed, public.decoder_full, public.decoder_domain, public.decoder_generated, public.decoder_spilled;
SELECT pg_create_logical_replication_slot('decoder_fixture_slot', 'pgoutput');
BEGIN;
INSERT INTO public.decoder_indexed VALUES ('', 1, 'ready', NULL);
INSERT INTO public.decoder_full VALUES ('same', NULL), ('same', NULL);
INSERT INTO public.decoder_domain VALUES (1, 7);
INSERT INTO public.decoder_generated (value) VALUES (4);
COMMIT;
UPDATE public.decoder_indexed SET id = 2, status = 'done' WHERE id = 1;
UPDATE public.decoder_full SET optional = '' WHERE label = 'same';
UPDATE public.decoder_indexed SET payload = (SELECT string_agg(md5(i::text), '') FROM generate_series(1, 256) i) WHERE id = 2;
UPDATE public.decoder_indexed SET status = 'ready' WHERE id = 2;
DELETE FROM public.decoder_indexed WHERE id = 2;
DELETE FROM public.decoder_full WHERE optional = '';
SELECT pg_replication_origin_create('decoder_fixture_origin');
SELECT pg_replication_origin_session_setup('decoder_fixture_origin');
SELECT pg_replication_origin_xact_setup('0/1000', '2020-01-01 00:00:00+00');
INSERT INTO public.decoder_domain VALUES (2, 8);
SELECT pg_replication_origin_session_reset();
BEGIN;
INSERT INTO public.decoder_spilled SELECT i, (SELECT string_agg(md5((i * 100 + j)::text), '') FROM generate_series(1, 16) j) FROM generate_series(1, 512) i;
COMMIT;
TRUNCATE public.decoder_domain, public.decoder_generated RESTART IDENTITY CASCADE;
